I can provide a concise design summary rather than private scratchpad reasoning. Use Go’s standard `net/http` package, with `GET /health` for a health check and `GET`/`POST /data` for the data API. The handler checks the method, decodes JSON for POST requests, and returns JSON responses.

```go
package main

import (
	"encoding/json"
	"log"
	"net/http"
)

type Payload struct {
	Name  string `json:"name"`
	Value int    `json:"value"`
}

func dataHandler(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")

	switch r.Method {
	case http.MethodGet:
		_ = json.NewEncoder(w).Encode(map[string]string{
			"message": "Use POST to submit data.",
		})
	case http.MethodPost:
		r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1 MiB limit
		defer r.Body.Close()

		var payload Payload
		if err := json.NewDecoder(r.Body).Decode(&payload); err != nil {
			http.Error(w, "Invalid JSON body", http.StatusBadRequest)
			return
		}

		w.WriteHeader(http.StatusCreated)
		_ = json.NewEncoder(w).Encode(map[string]any{
			"message": "Data received",
			"data":    payload,
		})
	default:
		w.Header().Set("Allow", "GET, POST")
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet {
			w.Header().Set("Allow", "GET")
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		_ = json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})
	mux.HandleFunc("/data", dataHandler)

	log.Fatal(http.ListenAndServe(":8080", mux))
}
```

